+import { sleep } from './sleep';
+
+const BACKOFF_MS = 60_000;
+
+/** Keeps one connection to an address alive. */
+export class Dialer {
+  private readonly backoffUntil = new Map<string, number>();
+  private running = false;
+
+  constructor(private readonly connect: (addr: string) => Promise<boolean>) {}
+
+  /** Starts the supervisor loop for `addr`. */
+  start(addr: string): void {
+    this.running = true;
+    void this.supervise(addr);
+  }
+
+  stop(): void {
+    this.running = false;
+  }
+
+  /** Whether `addr` may be dialed now. */
+  eligible(addr: string): boolean {
+    return (this.backoffUntil.get(addr) ?? 0) <= Date.now();
+  }
+
+  private async supervise(addr: string): Promise<void> {
+    while (this.running) {
+      if (this.eligible(addr)) {
+        const ok = await this.connect(addr);
+        if (ok) this.backoffUntil.delete(addr);
+        else this.backoffUntil.set(addr, Date.now() + BACKOFF_MS);
+      }
+      await sleep(1_000);
+    }
+  }
+}
