+import { Dialer } from './net/dialer';
+import { handshake } from './net/handshake';
+
+/** The app's one connection to its node, created at startup. */
+export class Client {
+  private readonly dialer = new Dialer(handshake);
+
+  constructor(private readonly addr: string) {
+    this.dialer.start(addr);
+  }
+
+  close(): void {
+    this.dialer.stop();
+  }
+}
